<template>
  <div class="admin-page"><router-link to="/admin" class="back-link">← 返回后台</router-link><div class="page-title">金币统计</div>
    <div class="card" style="margin-bottom:8px;padding:12px;"><div style="display:flex;gap:6px;align-items:center;"><input type="date" v-model="dateFrom" class="input" style="flex:1;" /><span style="color:var(--text-muted);font-size:12px;">至</span><input type="date" v-model="dateTo" class="input" style="flex:1;" /><button class="btn btn-primary btn-sm" @click="doSearch">查询</button></div></div>
    <div class="summary-grid"><div class="summary-card"><div class="summary-value" style="color:var(--green-text);">+{{ stats.total_add }}</div><div class="summary-label">总增加</div></div><div class="summary-card"><div class="summary-value" style="color:var(--red);">{{ stats.total_deduct }}</div><div class="summary-label">总减少</div></div><div class="summary-card"><div class="summary-value">{{ stats.net }}</div><div class="summary-label">净变动</div></div><div class="summary-card"><div class="summary-value">{{ stats.total_ops }}</div><div class="summary-label">操作次数</div></div></div>
    <div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>管理员</th><th>增加</th><th>扣减</th></tr></thead><tbody><tr v-for="a in (stats.by_admin||[])" :key="a.admin_id"><td>{{ a.admin_name }}</td><td style="color:var(--green-text);font-weight:600;">+{{ a.add }}</td><td style="color:var(--red);font-weight:600;">-{{ a.deduct }}</td></tr></tbody></table></div></div>
  </div>
