<script setup>import { ref, reactive, inject } from 'vue'; import { useAppStore } from '../stores/app'; const store = useAppStore(); const showToast = inject('showToast'); const dateFrom = ref('2026-05-01'); const dateTo = ref('2026-05-31'); const stats = reactive({total_add:0,total_deduct:0,net:0,total_ops:0,by_admin:[]}); async function doSearch(){try{const r=await store.fetchStats(dateFrom.value,dateTo.value);Object.assign(stats,r)}catch(e){showToast('查询失败','error')}}</script>